// 通用 split 函数
vector<int> split(const string& str, const string& delimiter) {
    vector<int> result;
    size_t start = 0;
    size_t end = str.find(delimiter);
    while (end != string::npos) {
        result.push_back(stoi(str.substr(start, end - start)));
        start = end + delimiter.length();
        end = str.find(delimiter, start);
    }
    // 添加最后一个部分
    result.push_back(stoi(str.substr(start)));
    return result;
}
​
// 递归回溯 尝试不同组合方案将文件放入指定数量光盘中
bool DFS(vector<int>& num, vector<int>& capacity, int index) {
    if (index == num.size()) {
        return true;
    }
​
    int weight = num[index];
    for (int i = 0; i < capacity.size(); i++) {
        if (capacity[i] + weight > 500) {
            continue;
        }
        // 剪枝 重复递归逻辑不考虑
        if (i > 0 && capacity[i] == capacity[i-1]) {
            continue;
        }
        // 递归回溯
        capacity[i] += weight;
        if (DFS(num, capacity, index + 1)) {
            return true;
        }
        capacity[i] -= weight;
    }
    return false;
}
​
bool check(vector<int>& num, int count) {
    vector<int> capacity(count, 0);
    return DFS(num, capacity, 0);
}
