int main() {
    string input;
    getline(cin, input);
    vector<int> num = split(input, ",");
​
    // 降序排序，能提高代码执行效率
    sort(num.rbegin(), num.rend());
​
    int left = 1, right = num.size();
    // 二分 枚举光盘数量
    while (left < right) {
        int mid = (left + right) >> 1;
        if (check(num, mid)) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    cout << left;
    return 0;
}

