package main
​
import (
    "bufio"
    "fmt"
    "os"
    "sort"
    "strconv"
    "strings"
)
​
// 回溯递归
func dfs(num []int, capacity []int, index int) bool {
    if index == len(num) {
        return true
    }
    weight := num[index]
    for i := 0; i < len(capacity); i++ {
        if capacity[i]+weight > 500 {
            continue
        }
        // 剪枝 同样情况的递归搜索
        if i > 0 && capacity[i] == capacity[i-1] {
            continue
        }
        capacity[i] += weight
        if dfs(num, capacity, index+1) {
            return true
        }
        capacity[i] -= weight
    }
    return false
}
​
func check(num []int, count int) bool {
    capacity := make([]int, count)
    return dfs(num, capacity, 0)
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    line, _ := reader.ReadString('\n')
    parts := strings.Split(strings.TrimSpace(line), ",")
    var num []int
    for _, p := range parts {
        val, _ := strconv.Atoi(p)
        num = append(num, val)
    }
​
    // 降序排序，优化效率
    sort.Slice(num, func(i, j int) bool { return num[i] > num[j] })
​
    left, right := 1, len(num)
    for left < right {
        mid := (left + right) / 2
        if check(num, mid) {
            right = mid
        } else {
            left = mid + 1
        }
    }
    fmt.Println(left)
}
